function goStep(i){i=i===2?2:1;activeStep=i;document.querySelectorAll('[data-panel]').forEach(e=>{const n=Number(e.dataset.panel);e.hidden=!(i===1?n<=2:n>=3);});document.querySelectorAll('[data-step]').forEach(e=>{e.classList.toggle('selected',Number(e.dataset.step)===i);e.setAttribute('aria-current',Number(e.dataset.step)===i?'step':'false');});$('object-config').hidden=i!==1;$('reaction-config').hidden=i!==1;$('publish-config').hidden=i!==2;$('object-list-host').hidden=i!==1;$('scene-preview-tools').hidden=i!==1;$('scene-view-tools').hidden=i!==1;if(i===2)$('publish-config').append($('status'));else document.querySelector('main>aside').append($('status'));updateGuide();}
function updateGuide(){if(project.experienceMode==='space'&&$('guide-text'))$('guide-text').dataset.mode='space';if(!$('guide-title'))return;$('guide-title').textContent=(activeStep+1)+'. '+WORKSPACES[activeStep];$('guide-text').textContent=['マーカーを登録し、同じ画面でシーンを作成・選択します。作品は次の画面で配置します。','左で作品を選び、右で配置・表示・反応を設定します。','編集データの保存と、公開版の更新を同じ画面で行います。公開完了後のQRでiPhoneを開いてください。'][activeStep];if(project.experienceMode==='space')$('guide-text').textContent+= ' 空間配置モード：同じシーンの全作品を共通原点で表示します。保存・公開後、iPhoneで一括配置してください。';$('breadcrumb').textContent=project.title+' ＞ '+(marker()?.name||'マーカー未登録')+' ＞ '+scene.name+' ＞ '+(selected?.name||'作品未選択');$('selected-label').textContent=selected?'選択作品：'+selected.name:'作品を選択してください';$('reaction-summary').textContent=reactionText(selected,project);$('reaction-summary').hidden=true;$('exclusive-tap').disabled=!selected;$('connection').textContent=session?.authenticated?'GitHub接続済み：'+session.repository:session?.canLocalPublish?'MacのGit認証で直接公開できます。':'直接公開にはlocalhostまたはGitHub接続済みサーバーが必要です。';if(publishedURL)$('guide-text').textContent+=' '+(publishedFingerprint&&publishedFingerprint!==fingerprint()?'未公開の変更があります。':'公開URL：'+publishedURL);}

function updateShadow(){const enabled=scene.objects.some(o=>o.shadow);renderer.shadowMap.enabled=enabled;renderer.shadowMap.type=THREE.PCFShadowMap;const settings=shadowSettings(project);light.position.set(...shadowLightPosition(settings.direction));configureShadowLight(light,shadowBounds(marker()?.aspect??1,settings.extent));light.castShadow=enabled;if(shadowPlane){shadowPlane.scale.set(settings.extent,settings.extent,1);shadowPlane.visible=enabled;shadowPlane.material.opacity=project.shadowOpacity??.3;}}

async function initProjectStorage(){try{if(session?.canSaveDraft){const r=await fetch('/api/projects');if(r.ok){const data=await r.json();for(const f of data.folders){const o=document.createElement('option');o.value=f.id;o.textContent=f.name;$('project-folder').append(o);}if(serverEnabled){const current=data.projects.find(p=>p.id===project.id);$('project-folder').value=current?.folderId||'';}}}const db=await dbPromise;const handle=await new Promise((resolve,reject)=>{const q=db.transaction('draft').objectStore('draft').get('directory');q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);});if(handle){selectedDirectory=handle;$('directory-label').textContent='PC保存先：'+handle.name;}$('choose-directory').disabled=!window.showDirectoryPicker;}catch(e){status('保存先の確認：'+e.message);}}
function projectThumbnail(){try{renderer.render(world,camera);const c=document.createElement('canvas');c.width=320;c.height=200;c.getContext('2d').drawImage(renderer.domElement,0,0,320,200);return c.toDataURL('image/jpeg',.7);}catch{return undefined;}}
async function saveServerProject(automatic=false){if(!session?.canSaveDraft)throw new Error('制作サーバーでGitHubにログインして保存してください。');if(serverBusy){if(automatic){serverTimer=setTimeout(()=>saveServerProject(true).catch(e=>status(e.message)),3000);return;}throw new Error('保存処理中です。');}serverBusy=true;try{const before=fingerprint(),data=await snapshot(true);if(!serverSavedAt){const old=await fetch('/api/drafts/'+encodeURIComponent(project.id));if(old.ok){const existing=await old.json();if(automatic||!confirm('同じIDの保存があります。現在の編集で上書きしますか？'))throw new Error('別の体験IDを指定するか、一覧から既存プロジェクトを開いてください。');serverSavedAt=existing.savedAt;}else if(old.status!==400&&old.status!==404)throw new Error('既存の保存を確認できません。');}data.meta={folderId:$('project-folder').value,thumbnail:projectThumbnail(),expectedSavedAt:serverSavedAt};const r=await fetch('/api/drafts/'+encodeURIComponent(project.id),{method:'PUT',headers:{'Content-Type':'application/json','X-CSRF-Token':session.csrf||''},body:JSON.stringify(data)});const result=await r.json();if(!r.ok)throw new Error(result.error);serverSavedAt=result.savedAt;serverEnabled=true;await persistDraft();if(fingerprint()===before)savedFingerprint=before;updateGuide();$('save-state').textContent='プロジェクト保存済み '+new Date(result.savedAt).toLocaleTimeString();if(!automatic)status('プロジェクト一覧へ保存しました。Web版は以後の変更を自動保存します。');}finally{serverBusy=false;}}



